def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    s = [int(x) for x in lines[1].split()]
    m = int(lines[2])
    actions = []
    for i in range(m):
        parts = lines[3 + i].split()
        actions.append((parts[0], int(parts[1])))

    # Sort heroes by strength descending
    # We only care about the heroes that could be picked/banned
    # Since m <= 20, we only need to track at most top m+10 heroes
    # but to be safe, let's use n
    sorted_heroes = sorted(enumerate(s), key=lambda x: -x[1])
    strengths = [h[1] for h in sorted_heroes]
    # For memoization, we track which heroes are still on board
    # Since m <= 20 and we do picks and bans, we only remove heroes

    from functools import lru_cache

    # For n up to 100, we can't use a full bitmask
    # But only m heroes are picked/banned total
    # So we only need to consider the m strongest heroes that matter
    # Actually, the optimal strategy: always consider picking/banning strongest available

    # Helper: get best result for given state using min/max
    # State: (move_index, sorted_heroes_active)
    # Since heroes are sorted by strength, we can track which are removed

    @lru_cache(maxsize=None)
    def solve(move_idx, mask):
        if move_idx == m:
            return 0

        action_type, team = actions[move_idx]

        if action_type == 'p':
            # Pick: team wants to maximize their advantage
            # Team 1 maximizes (Team1_strength - Team2_strength)
            # Team 2 minimizes (Team1_strength - Team2_strength)
            if team == 1:
                best = float('-inf')
                for i in range(len(strengths)):
                    if not (mask & (1 << i)):
                        val = strengths[i] + solve(move_idx + 1, mask | (1 << i))
                        if val > best:
                            best = val
                return best
            else:
                best = float('inf')
                for i in range(len(strengths)):
                    if not (mask & (1 << i)):
                        val = -strengths[i] + solve(move_idx + 1, mask | (1 << i))
                        if val < best:
                            best = val
                return best
        else:
            # Ban: remove a hero from pool
            # Both teams want to ban the strongest available hero
            if team == 1:
                max_st = -1
                ban_idx = 0
                for i in range(len(strengths)):
                    if not (mask & (1 << i)):
                        if strengths[i] > max_st:
                            max_st = strengths[i]
                            ban_idx = i
                return solve(move_idx + 1, mask | (1 << ban_idx))
            else:
                max_st = -1
                ban_idx = 0
                for i in range(len(strengths)):
                    if not (mask & (1 << i)):
                        if strengths[i] > max_st:
                            max_st = strengths[i]
                            ban_idx = i
                return solve(move_idx + 1, mask | (1 << ban_idx))

    result = solve(0, 0)
    return str(result)
