def solution(input_text):
    """
    For each abbreviation, find the year it corresponds to.
    """
    lines = input_text.strip().split('\n')
    if not lines:
        return ""

    n = int(lines[0])
    abbreviations = [lines[i] for i in range(1, n + 1)]

    abb_map = {}
    used = set()
    year = 1989

    # Build the complete abbreviation to year mapping
    while True:
        # Find shortest unused suffix for this year
        length = 1
        while True:
            if length > len(str(year)):
                break
            suffix = str(year)[-length:]
            if suffix not in used:
                abb_map[suffix] = year
                used.add(suffix)
            length += 1

        needed = {abbr[4:] for abbr in abbreviations if len(abbr) > 4}
        if needed <= used:
            break
        if year > 200000:  # Safety limit
            break
        year += 1

    # Look up each abbreviation
    results = [str(abb_map[abbr[4:]]) for abbr in abbreviations if abbr.startswith("IAO'")]
    return '\n'.join(results)
