import math

def solution(input_str):
    n, m, k = map(int, input_str.split())

    # Total number of arrangements: C(n+m, n)
    def combinations(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        return math.factorial(n_val) // (math.factorial(r_val) * math.factorial(n_val - r_val))

    total_arrangements = combinations(n + m, n)

    # Number of valid arrangements: paths from (0, k) to (n, k + n - m)
    # staying at or above y = 0 throughout the path

    # If k >= m, we can always give change
    if k >= m:
        return f"{1.0:.12f}\n"

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_valid(i, j, current):
        """
        i: number of 10 euro people remaining
        j: number of 20 euro people remaining
        current: current number of 10 euro banknotes

        Returns number of valid ways to arrange the remaining people
        """
        if j == 0:
            return 1
        if i == 0:
            return 0 if current < min(1, m - (n - i)) else 0

        result = 0
        # Place a 10 euro person
        result += count_valid(i - 1, j, current + 1)
        # Place a 20 euro person if we have change
        if current > 0:
            result += count_valid(i, j - 1, current - 1)
        return result

    # Simpler approach using combinatorial method
    # This is equivalent to counting paths that don't go below 0
    # Starting at height k, with n up steps and m down steps

    # Use enumeration cleverly
    def count_valid_paths(n_val, m_val, k_val):
        if m_val == 0:
            return 1
        if k_val >= m_val:
            return combinations(n_val + m_val, n_val)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, j, h):
            """Count valid paths with i 10-users left and j 20-users left at height h"""
            if j == 0:
                return 1
            if i == 0:
                return 0 if h <= 0 else 0  # Shouldn't happen with correct logic
            # 10 euro person: increases height
            count1 = dp(i - 1, j, h + 1)
            # 20 euro person: decreases height (only if h > 0)
            count2 = 0
            if h > 0:
                count2 = dp(i, j - 1, h - 1)
            return count1 + count2

        return dp(n, m, k)

    valid_arrangements = count_valid_paths(n, m, k)

    if total_arrangements == 0:
        prob = 1.0 if valid_arrangements == 0 else 0.0
    else:
        prob = valid_arrangements / total_arrangements

    return f"{prob:.12f}\n"
