        for ai, hi, li, ri in trees:
            if survive_prob == 0.0:
                break

            destroy_prob = 0.0

            # Tree falls left: destroys mushrooms in [ai - hi, ai)
            if (bj >= ai - hi) and (bj < ai):
                destroy_prob += li

            # Tree falls right: destroys mushrooms in (ai, ai + hi]
            if (bj > ai) and (bj <= ai + hi):
                destroy_prob += ri

            # If destroy_prob > 0, multiply survival probability
            if destroy_prob > 0:
                survive_prob *= (1.0 - destroy_prob / 100.0)

        result += zj * survive_prob

    return f"{result:.10f}\n"
