Looking at this problem, I need to implement a game theory solution for a binary tree where:
- Pieguy wants to maximize the root value
- Piegirl wants to minimize the root value
- Players alternate turns starting with Pieguy
- They can merge sibling leaves and keep one of their values

The key insight is that for each internal node, when both its children have been reduced to single values, we merge them. The turn number for this merge depends on how many leaves are in each subtree.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    if idx < len(lines) and lines[idx] == '':
        idx += 1

    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty line before each test case
        if idx < len(lines) and lines[idx] == '':
            idx += 1

        n = int(lines[idx])
        idx += 1

        # Parse tree
        tree = [None] * n

        for i in range(n):
            parts = lines[idx].split()
            idx += 1
            if parts[0] == '-1':
                left_child = int(parts[1])
                right_child = int(parts[2])
                tree[i] = {'l': left_child, 'r': right_child, 'is_leaf': False}
            else:
                tree[i] = {'val': int(parts[0]), 'is_leaf': True}

        # Compute using post-order traversal
        def compute(i):
            if tree[i]['is_leaf']:
                return {'leaf_count': 1, 'value': tree[i]['val']}

            l_result = compute(tree[i]['l'])
            r_result = compute(tree[i]['r'])

            l_count = l_result['leaf_count']
            r_count = r_result['leaf_count']

            # Total moves before reaching the merge at this node
            moves_before = (l_count - 1) + (r_count - 1)
            turn = moves_before  # 0-indexed turn number

            # Even turn: Pieguy maximizes, odd turn: Piegirl minimizes
            if turn % 2 == 0:
                result_value = max(l_result['value'], r_result['value'])
            else:
                result_value = min(l_result['value'], r_result['value'])

            return {'leaf_count': l_count + r_count, 'value': result_value}

        root_result = compute(0)
        results.append(str(root_result['value']))

    return '\n'.join(results)
