        # Run DFS in reverse
        visited = [False] * (n + 1)
        stack = [node]
        while stack:
            u = stack.pop()
            if visited[u]:
                continue
            visited[u] = True
            for v in redirected_adj[u]:
                if not visited[v]:
                    stack.append(v)

        return all(visited)

    # Check if the current orientation works
    redirect_adj = defaultdict(list)
    for i, (u, v) in enumerate(edges):
        if result[i] == u:
            redirect_adj[u].append(v)
        else:
            redirect_adj[v].append(u)

    if not is_strongly_connected(1, n, redirect_adj):
        return '0'

    # Build output
    output = []
