            val_l = arr[idx_l]
            val_r = arr[idx_r]

            if val_l != val_r:
                # Calculate inversion change
                change = 1 if val_r > val_l else 0  # (l, r) pair
                change -= 1 if val_l > val_r else 0

                # For elements between: (l, i) and (i, r) pairs
                if val_r < val_l:
