                    # After swap it becomes > val_r, might form inversion
                    count_between = count_less_than(val_r, idx_l + 1, idx_r - 1)
                    change += count_less_than(val_r, idx_l + 1, idx_r - 1) - count_less_than(val_l, idx_l + 1, idx_r - 1)
                else:
                    count_between = count_less_than(val_l, idx_l + 1, idx_r - 1)
                    change += count_less_than(val_l, idx_l + 1, idx_r - 1) - count_less_than(val_r, idx_l + 1, idx_r - 1)

                # Elements > val_l or < val_r affected
                from_val_to_r = count_less_than(val_r, idx_l + 1, idx_r - 1)
                to_val_l_from = count_less_than(val_l, idx_l + 1, idx_r - 1)

                inversions += change

        # Count fresh inversions (simple but O(n²) per query)
        inversions = 0
        for i in range(n):
