from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    n, d = int(parts[0]), int(parts[1])
    c = list(map(int, lines[1].split()))

    # Generate all possible subset sums
    all_sums = set()
    all_sums.add(0)
    for i in range(1, n + 1):
        for combo in combinations(c, i):
            all_sums.add(sum(combo))

    # dp[s] = minimum days to reach sum s
    dp = {}
    dp[0] = 0

    # Process day by day to find reachable states
    reachable_on_previous_day = {0}

    for day in range(1, 1 + n + d // 10000 + 10):
        next_reachable = set()
        for s in reachable_on_previous_day:
            # From current sum s, can reach any other sum t at most d away
            # But must be achievable sum
            for t in all_sums:
                if abs(t - s) <= d:
                    next_reachable.add(t)

        # Record minimum days for each reachable sum
        for t in next_reachable:
            if t not in dp:
                dp[t] = day

        reachable_on_previous_day = next_reachable
        if len(next_reachable) == 0:
            break

        # If we've reached all achievable sums, we can stop
        if all_sums.issubset(reachable_on_previous_day):
            break

    if not dp:
        return "0 0"

    max_sum = max(dp.keys())
    min_days = dp[max_sum]

    # If max_sum isn't reachable through days, return largest reachable
    if max_sum not in dp or dp[max_sum] == 0:
        max_sum = max(s for s in dp if dp[s] > 0)
        min_days = dp[max_sum]

    return f"{max_sum} {min_days}"


