def solution(s):
    lines = s.strip().split('\n')
    idx = 0
    if idx >= len(lines):
        return ''
    t = int(lines[idx])
    idx += 1

    output_parts = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        wires = []
        for i in range(n):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            wires.append([x, y])  # Use list for mutability

        if n <= 1:
            output_parts.append('0')
            continue

        # Union-Find for connected components
        parent = list(range(n))

        def find(i):
            root = i
            while parent[root] != root:
                root = parent[root]
            while parent[i] != root:
                next_i = parent[i]
                parent[i] = root
                i = next_i
            return root

        def unite(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j

        # Group wires by contact points
        contact_to_wires = {}
        for i in range(n):
            x, y = wires[i][0], wires[i][1]
            if x not in contact_to_wires:
                contact_to_wires[x] = set()
            contact_to_wires[x].add(i)
            if y not in contact_to_wires:
                contact_to_wires[y] = set()
            contact_to_wires[y].add(i)

        # Union wires that share contact points
        for point, wire_set in contact_to_wires.items():
            wires = list(wire_set)
            for i in range(len(wires)):
                for j in range(i + 1, len(wires)):
                    unite(wires[i], wires[j])

        # Count components and get representatives
        components = {}
        for i in range(n):
            root = find(i)
            if root not in components:
                components[root] = i

        num_components = len(components)
        representatives = list(components.values())

        if num_components == 1:
            output_parts.append('0')
        else:
            # We need num_components - 1 operations
            # Strategy: pick first contact of each rep's wire and make them all share a single contact

            # Find wires and their contact points
            rep_wires = []
            for rep in representatives:
                rep_wires.append(rep)  # wire index (0-based)

            # Find a connection point on each wire to modify
            # Prefer the first contact point of each wire
            contacts_to_change = []
            for i, w_idx in enumerate(rep_wires):
                x, y = wires[w_idx]
                # Choose the smaller contact point (arbitrary choice)
                if x < y:
                    contacts_to_change.append((w_idx, x))
                else:
                    contacts_to_change.append((w_idx, y))

            # Find a new contact point that's not currently used by any of these wires
            used = set()
            for w_idx, cp in contacts_to_change:
                x, y = wires[w_idx]
                used.add(x)
                used.add(y)

            new_contact = 1
            while new_contact in used:
                new_contact += 1

            ops = []
            for w_idx, _ in contacts_to_change:
                ops.append(w_idx)

            # Sort the wires by their index for output order (we'll adjust later)
            # Actually, we should output in the order we process them
            # But the wires need to be modified - they will now share new_contact

            # Output k
            output_parts.append(str(num_components - 1))

            # For each wire, output the re-soldering
            for i, (w_idx, old_cp) in enumerate(contacts_to_change):
                output_parts.append(f"{w_idx + 1} {old_cp} {new_contact}")

    return '\n'.join(output_parts)
