    def can_cover_from_right(coverer, target):
        return p[coverer] >= coverer - target and coverer > target

    def find_coverage_for(pos):
        # Find a lantern that can cover pos (either from left or right)
        for j in range(pos):
            if direction[j] == 0 and can_cover_from_left(j, pos):
                return (j, 2)  # j covers to right (R)
        for j in range(pos + 1, n):
            if direction[j] == 0 and can_cover_from_right(j, pos):
                return (j, 1)  # j covers to left (L)
        return None

    def backtrack(idx):
        # Find first uncovered lantern
        first_uncovered = idx
        while first_uncovered < n and is_covered(first_uncovered):
            first_uncovered += 1

        if first_uncovered >= n:
            # All covered, check solution is valid and complete
            s = []
            for d in direction:
                if d == 0:
                    return None
                s.append('R' if d == 1 else 'L')
            if len(s) == n:
                return ''.join(s)
            return None

        # Find all possible ways to cover first_uncovered
        covers = find_coverage_for(first_uncovered)
        if covers is None:
            return None

        coverer_pos, d = covers

        # Try all possible coverers (greediest with backtracking)
        for j in range(n):
            if j == coverer_pos and direction[j] != 0:
                continue
            is_coverer = False
            if j < first_uncovered and p[j] >= first_uncovered - j and direction[j] == 0:
                is_coverer = True
                d_val = 2
            elif j > first_uncovered and p[j] >= j - first_uncovered and direction[j] == 0:
                is_coverer = True
                d_val = 1
            else:
                continue

            if is_coverer:
                direction[j] = d_val
                result = backtrack(first_uncovered + 1)
                if result is not None:
                    return result
                direction[j] = 0

        return None

    result = backtrack(0)
    if result is None:
        return "NO"
    return "YES\n" + result
