                    elif v in visited and v != u:
                        # Found a cycle
                        cycle_len = dist[u] + w - dist[v]
                        if cycle_len <= 0:
                            cycle_len = 0
                        cycle_gcd = gcd(cycle_gcd, abs(cycle_len))

        bfs_find_cycle_gcd()
        scc_cycle_gcd[scc] = cycle_gcd if cycle_gcd > 0 else 0

    # Process queries
    results = []
    for v, s, t in queries:
        if s == 0:
            results.append("YES")
            continue

        sc = scc_id[v]
        g = scc_cycle_gcd.get(sc, 0)

        if g == 0:
            results.append("NO")
        else:
            # Need d such that (s + d) % t == 0, where d is multiple of g
            # This requires gcd(g, t) | s
            g_common = gcd(g, t)
            if s % g_common == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results) + '\n'
